import{_ as i,y as r,a as s,o as a,a2 as t,D as o}from"./chunks/framework.DCcmcJcL.js";const v=JSON.parse('{"title":"Invoice Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/invoice-settings.md","filePath":"configure/invoice-settings.md","lastUpdated":1789395222000}'),c={name:"configure/invoice-settings.md"};function g(l,e,d,h,u,m){const n=r("ImagePopup");return a(),s("div",null,[e[0]||(e[0]=t('<h1 id="invoice-settings" tabindex="-1">Invoice Settings <a class="header-anchor" href="#invoice-settings" aria-label="Permalink to &quot;Invoice Settings&quot;">​</a></h1><p>These settings decide how invoice numbers are built, when invoices are due, what the invoice PDF shows, and whether reminders are sent for unpaid invoices.</p><p>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Invoice Settings</strong>.</p><h2 id="invoice-numbers" tabindex="-1">Invoice numbers <a class="header-anchor" href="#invoice-numbers" aria-label="Permalink to &quot;Invoice numbers&quot;">​</a></h2><ol><li>In <strong>Invoice Number Settings</strong>, enter the <strong>Invoice Number Prefix</strong>, such as <code>INV-</code>.</li><li>Enter the <strong>Invoice Number Length</strong>, a number from <code>0</code> to <code>10</code>.</li><li>Optionally, enter an <strong>Invoice Number Suffix</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),o(n,{src:"/images/configure/invoice-settings-numbers.png",alt:"Invoice Number Settings and Payment Terms sections of the Invoice Settings screen"}),e[1]||(e[1]=t('<p>The number is padded with zeros to the length you set, so a prefix of <code>INV-</code> and a length of <code>6</code> give invoice numbers such as <code>INV-000042</code>. Leave <strong>Invoice Number Generator</strong> empty unless a developer has built a custom number generator for your store. The invoice number settings are set per channel and per language, so set them before the channel issues its first invoice.</p><h2 id="payment-terms" tabindex="-1">Payment terms <a class="header-anchor" href="#payment-terms" aria-label="Permalink to &quot;Payment terms&quot;">​</a></h2><ol><li>In <strong>Payment Terms</strong>, enter the <strong>Due Duration</strong>, the number of days after the invoice date within which the invoice must be paid.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The due duration is set per channel.</p><h2 id="pdf-print-outs" tabindex="-1">PDF print outs <a class="header-anchor" href="#pdf-print-outs" aria-label="Permalink to &quot;PDF print outs&quot;">​</a></h2><ol><li>In <strong>PDF Print Outs</strong>, switch <strong>Display Invoice ID in Header</strong> on or off.</li><li>Switch <strong>Display Order ID in Header</strong> on or off. Both are on by default.</li><li>Under <strong>Logo</strong>, click <strong>Add Image</strong> and choose the logo to print on the invoice. A size of 131 × 30 px is recommended.</li><li>Enter the <strong>Footer text</strong> printed at the bottom of the PDF.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',6)),o(n,{src:"/images/configure/invoice-settings-pdf.png",alt:"PDF Print Outs and Invoice Reminders sections of the Invoice Settings screen"}),e[2]||(e[2]=t('<p>The logo is set per channel, and the footer text per channel and language.</p><h2 id="invoice-reminders" tabindex="-1">Invoice reminders <a class="header-anchor" href="#invoice-reminders" aria-label="Permalink to &quot;Invoice reminders&quot;">​</a></h2><p>Invoice reminders are emails sent to customers about invoices that are past their due date.</p><ol><li>In <strong>Invoice Reminders</strong>, enter the <strong>Maximum limit of reminders</strong> sent for one invoice.</li><li>Choose the <strong>Interval between reminders</strong>, from <strong>1 day</strong> to <strong>4 weeks</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>Reminders are sent once a day by the server&#39;s task scheduler. If they aren&#39;t sent, ask whoever manages your server to check that the scheduler is running.</p>',5))])}const f=i(c,[["render",g]]);export{v as __pageData,f as default};
